CREATE FUNCTION cmd_reject_regulatory_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Regulatory task receipts are immutable'; END $$;
CREATE TRIGGER cmd_regulatory_task_receipt_immutable BEFORE UPDATE OR DELETE ON cmd_regulatory_task_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_regulatory_mutation();
CREATE FUNCTION cmd_validate_regulatory_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE task cmd_actor_task_receipt%ROWTYPE; BEGIN SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id; IF task.actor_id<>NEW.actor_id OR task.skill_rule_id<>NEW.skill_rule_id OR task.law_level<>NEW.law_level OR task.circumstance_modifier<>NEW.illegal_modifier OR task.check_total<>NEW.check_total OR task.effect<>NEW.effect OR task.succeeded<>NEW.succeeded THEN RAISE EXCEPTION 'Regulatory receipt does not match its Law Level task'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER cmd_regulatory_task_receipt_valid AFTER INSERT ON cmd_regulatory_task_receipt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cmd_validate_regulatory_receipt();
